        sequence[i] = i;
    }

    for (int i = a; i < r; i++) {
        if (i % totalCycle < a) {
            std::unordered_set<int> usedNumbers;
            for (int j = i - 1; j >= i - a && j >= 0; j--) {
                usedNumbers.insert(sequence[j]);
            }
            for (int j = 0, k = 0; i % totalCycle != a && i < r; i++, j++) {
                while (usedNumbers.count(j)) j++;
                usedNumbers.insert(j);
                sequence[i] = j;
            }
