    std::unordered_set<int> finalUsed;
    for (int i = l; i < r; i++) {
        finalUsed.insert(sequence[i]);
    }
    int minDistinct = (int)finalUsed.size();

    for (int i = a; i < a + b && i < r; i++) {
        sequence[i] = sequence[b];
    }

    for (int i = a + b; i < r; i++) {
        if (i % totalCycle < a) {
            std::unordered_set<int> usedNumbers;
            for (int j = i - 1; j >= i - a && j >= 0; j--) {
                usedNumbers.insert(sequence[j]);
